import { HTTPError } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("problem details", (t, { it, expect, describe }) => {
  describe("default error format (problemDetails disabled)", () => {
    it("keeps the current JSON error response for HTTPError 404", async () => {
      t.app.config.debug = false;
      t.app.get("/users/1", () => {
        throw new HTTPError({
          status: 404,
          statusText: "Not Found",
          message: "Usuário não encontrado",
        });
      });

      const res = await t.fetch("/users/1");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
      expect(await res.json()).toEqual({
        status: 404,
        statusText: "Not Found",
        message: "Usuário não encontrado",
      });
    });

    it("includes stack only in debug mode", async () => {
      t.app.get("/users/1", () => {
        throw new HTTPError({ status: 404, statusText: "Not Found", message: "missing" });
      });

      const res = await t.fetch("/users/1");
      expect(await res.json()).toMatchObject({
        status: 404,
        message: "missing",
        stack: expect.any(Array),
      });
    });
  });
});

