import { H3, HTTPError, defineHandler, handleCacheHeaders, onResponse } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const PROBLEM = "application/problem+json";
const JSON_TYPE = "application/json;charset=UTF-8";

describeMatrix("problem details", (t, { it, expect, describe }) => {
  describe("config", () => {
    it("is off by default", () => {
      expect(new H3().config.problemDetails).toBeFalsy();
    });
  });

  describe("default error format (problemDetails disabled)", () => {
    it("keeps the current JSON error response for HTTPError 404", async () => {
      t.app.config.debug = false;
      t.app.get("/users/1", () => {
        throw new HTTPError({
          status: 404,
          statusText: "Not Found",
          message: "Usuário não encontrado",
        });
      });

      const res = await t.fetch("/users/1");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(JSON_TYPE);
      expect(await res.json()).toEqual({
        status: 404,
        statusText: "Not Found",
        message: "Usuário não encontrado",
      });
    });

    it("includes stack only in debug mode", async () => {
      t.app.get("/users/1", () => {
        throw new HTTPError({ status: 404, statusText: "Not Found", message: "missing" });
      });

      const res = await t.fetch("/users/1");
      expect(await res.json()).toMatchObject({
        status: 404,
        message: "missing",
        stack: expect.any(Array),
      });
    });
  });

  describe("problem details enabled", () => {
    const enable = () => {
      t.app.config.problemDetails = true;
      t.app.config.debug = false;
    };

    it("renders HTTPError as application/problem+json", async () => {
      enable();
      t.app.get("/users/1", () => {
        throw new HTTPError({
          status: 404,
          statusText: "Not Found",
          message: "Usuário não encontrado",
        });
      });

      const res = await t.fetch("/users/1");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toEqual({
        type: "about:blank",
        title: "Not Found",
        status: 404,
        detail: "Usuário não encontrado",
      });
    });

    it("uses about:blank as the default type for HTTPError 500", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({ status: 500, message: "boom" });
      });

      const res = await t.fetch("/");
      expect(await res.json()).toMatchObject({ type: "about:blank", status: 500 });
    });

    it("renders type and instance when given", async () => {
      enable();
      t.app.get("/pedidos/42", () => {
        throw new HTTPError({
          status: 403,
          type: "https://exemplo.com/erros/sem-permissao",
          instance: "/pedidos/42",
          message: "Sem permissão",
        });
      });

      const res = await t.fetch("/pedidos/42");
      expect(await res.json()).toMatchObject({
        type: "https://exemplo.com/erros/sem-permissao",
        instance: "/pedidos/42",
      });
    });

    it("omits title when statusText is absent", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({ status: 400, message: "bad" });
      });

      const res = await t.fetch("/");
      const body = await res.json();
      expect(body).not.toHaveProperty("title");
