import { H3, HTTPError, defineHandler, handleCacheHeaders, onResponse } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const PROBLEM = "application/problem+json";
const JSON_TYPE = "application/json;charset=UTF-8";

describeMatrix("problem details", (t, { it, expect, describe }) => {
  describe("config", () => {
    it("is off by default", () => {
      expect(new H3().config.problemDetails).toBeFalsy();
    });
  });

  describe("default error format (problemDetails disabled)", () => {
    it("keeps the current JSON error response for HTTPError 404", async () => {
      t.app.config.debug = false;
      t.app.get("/users/1", () => {
        throw new HTTPError({
          status: 404,
          statusText: "Not Found",
          message: "Usuário não encontrado",
        });
      });

      const res = await t.fetch("/users/1");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(JSON_TYPE);
      expect(await res.json()).toEqual({
        status: 404,
        statusText: "Not Found",
        message: "Usuário não encontrado",
      });
    });

    it("includes stack only in debug mode", async () => {
      t.app.get("/users/1", () => {
        throw new HTTPError({ status: 404, statusText: "Not Found", message: "missing" });
      });

      const res = await t.fetch("/users/1");
      expect(await res.json()).toMatchObject({
        status: 404,
        message: "missing",
        stack: expect.any(Array),
      });
    });
  });

  describe("problem details enabled", () => {
    const enable = () => {
      t.app.config.problemDetails = true;
      t.app.config.debug = false;
    };

    it("renders HTTPError as application/problem+json", async () => {
      enable();
      t.app.get("/users/1", () => {
        throw new HTTPError({
          status: 404,
          statusText: "Not Found",
          message: "Usuário não encontrado",
        });
      });

      const res = await t.fetch("/users/1");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toEqual({
        type: "about:blank",
        title: "Not Found",
        status: 404,
        detail: "Usuário não encontrado",
      });
    });

    it("uses about:blank as the default type for HTTPError 500", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({ status: 500, message: "boom" });
      });

      const res = await t.fetch("/");
      expect(await res.json()).toMatchObject({ type: "about:blank", status: 500 });
    });

    it("renders type and instance when given", async () => {
      enable();
      t.app.get("/pedidos/42", () => {
        throw new HTTPError({
          status: 403,
          type: "https://exemplo.com/erros/sem-permissao",
          instance: "/pedidos/42",
          message: "Sem permissão",
        });
      });

      const res = await t.fetch("/pedidos/42");
      expect(await res.json()).toMatchObject({
        type: "https://exemplo.com/erros/sem-permissao",
        instance: "/pedidos/42",
      });
    });

    it("omits title when statusText is absent", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({ status: 400, message: "bad" });
      });

      const res = await t.fetch("/");
      const body = await res.json();
      expect(body).not.toHaveProperty("title");
      expect(body).toMatchObject({ status: 400, detail: "bad" });
    });

    it("renders a plain Error as a 500 problem details response", async () => {
      enable();
      t.app.config.silent = true;
      t.app.get("/", () => {
        throw new Error("falha inesperada");
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      t.errors = [];
    });

    it("hides detail and stack of unhandled errors", async () => {
      enable();
      t.app.config.silent = true;
      t.app.get("/", () => {
        throw new Error("segredo interno");
      });

      const res = await t.fetch("/");
      const text = await res.text();
      expect(res.status).toBe(500);
      expect(text).not.toContain("segredo interno");
      expect(text).not.toContain("stack");
      expect(JSON.parse(text)).toEqual({ type: "about:blank", status: 500 });
      t.errors = [];
    });

    it("keeps data and body as extension members", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({
          status: 422,
          statusText: "Unprocessable",
          message: "Inválido",
          data: { campo: "email" },
          body: { topLevel: "works" },
        });
      });

      const res = await t.fetch("/");
      expect(await res.json()).toEqual({
        type: "about:blank",
        title: "Unprocessable",
        status: 422,
        detail: "Inválido",
        data: { campo: "email" },
        topLevel: "works",
      });
    });

    it("does not let body override reserved members", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({
          status: 422,
          statusText: "Unprocessable",
          message: "real",
          body: {
            status: 1,
            type: "forged",
            title: "forged",
            detail: "forged",
            instance: "forged",
          },
        });
      });

      const res = await t.fetch("/");
      expect(await res.json()).toEqual({
        type: "about:blank",
        title: "Unprocessable",
        status: 422,
        detail: "real",
      });
    });

    it("includes stack when debug is enabled", async () => {
      t.app.config.problemDetails = true;
      t.app.config.debug = true;
      t.app.get("/", () => {
        throw new HTTPError({ status: 400, message: "bad" });
      });

      const res = await t.fetch("/");
      expect(await res.json()).toMatchObject({ stack: expect.any(Array) });
    });

    it("keeps error headers and errHeaders, with set-cookie not duplicated", async () => {
      enable();
      t.app.use((event) => {
        event.res.errHeaders.set("x-error", "prepared");
        event.res.errHeaders.append("set-cookie", "prepared=1");
        throw new HTTPError({
          status: 422,
          statusText: "Unprocessable",
          headers: { "x-error-own": "own", "set-cookie": "error=1" },
        });
      });

      const res = await t.fetch("/");
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(res.headers.get("x-error")).toBe("prepared");
      expect(res.headers.get("x-error-own")).toBe("own");
      expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
    });

    it("sends no body for HEAD requests", async () => {
      enable();
      t.app.get("/", () => {
        throw new HTTPError({ status: 404, message: "missing" });
      });

      const res = await t.fetch("/", { method: "HEAD" });
      expect(res.status).toBe(404);
      expect(res.headers.get("content-length")).toBeNull();
      expect(await res.text()).toBe("");
    });

    it("lets onError replace the problem details response", async () => {
      enable();
      t.app.config.onError = () => new Response("custom", { status: 501 });
      t.app.get("/", () => {
        throw new HTTPError({ status: 400, message: "bad" });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(501);
      expect(await res.text()).toBe("custom");
    });

    it("renders unmatched routes as problem details", async () => {
      enable();
      const res = await t.fetch("/missing");
      expect(res.status).toBe(404);
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toMatchObject({ status: 404, detail: expect.any(String) });
    });

    it("renders errors thrown after handleCacheHeaders as problem details", async () => {
      enable();
      t.app.get("/", (event) => {
        handleCacheHeaders(event, { maxAge: 60 });
        throw new HTTPError({ status: 404, message: "gone" });
      });

      const res = await t.fetch("/");
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toMatchObject({ status: 404, detail: "gone" });
    });

    it("renders errors thrown by a defineHandler route as problem details", async () => {
      enable();
      t.app.get(
        "/",
        defineHandler(() => {
          throw new HTTPError({ status: 503, statusText: "Unavailable", message: "try later" });
        }),
      );

      const res = await t.fetch("/");
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toMatchObject({ status: 503, title: "Unavailable" });
    });

    it("renders errors thrown before an event stream starts as problem details", async () => {
      enable();
      t.app.get("/events", (event) => {
        if (!event.req.headers.get("authorization")) {
          throw new HTTPError({ status: 401, statusText: "Unauthorized", message: "login" });
        }
        return createEventStream(event);
      });

      const res = await t.fetch("/events", { headers: { accept: "text/event-stream" } });
      expect(res.status).toBe(401);
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toMatchObject({ status: 401, detail: "login" });
    });

    it("renders a returned HTTPError as problem details through an onResponse middleware", async () => {
      enable();
      t.app.use(onResponse(() => {}));
      t.app.get("/", () => new HTTPError({ status: 409, message: "conflict" }));

      const res = await t.fetch("/");
      expect(res.status).toBe(409);
      expect(res.headers.get("content-type")).toBe(PROBLEM);
      expect(await res.json()).toMatchObject({ status: 409, detail: "conflict" });
    });
  });
});

